"""Source-free frame perception helpers for cracking.

This module is deliberately observational: it derives compact symbolic state
from `env.frame()` and `env.clone()` only. It is a cofibration-style scaffold:
raw pixels are embedded into a monotone tower of reusable observations
(components -> objects -> action deltas -> replay states). Candidate level
logic should be written against these quotients, then replay-validated by the
harness. No game source or prior solution history is read here.
"""
from collections import deque
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

UP, DOWN, LEFT, RIGHT, USE = 1, 2, 3, 4, 5
ACTIONS = (UP, DOWN, LEFT, RIGHT, USE)
DIRS = {UP: (-1, 0), DOWN: (1, 0), LEFT: (0, -1), RIGHT: (0, 1)}
ACTION_NAME = {UP: "UP", DOWN: "DOWN", LEFT: "LEFT", RIGHT: "RIGHT", USE: "USE"}


@dataclass(frozen=True)
class Blob:
    color: int
    bbox: Tuple[int, int, int, int]  # r0, c0, r1, c1 inclusive
    area: int
    centroid: Tuple[float, float]

    @property
    def top_left(self):
        return self.bbox[0], self.bbox[1]

    @property
    def size(self):
        r0, c0, r1, c1 = self.bbox
        return r1 - r0 + 1, c1 - c0 + 1


def arr(frame) -> np.ndarray:
    return np.asarray(frame)


def color_counts(frame) -> Dict[int, int]:
    vals, cnts = np.unique(arr(frame), return_counts=True)
    return {int(v): int(c) for v, c in zip(vals, cnts)}


def connected_components(frame, colors: Optional[Iterable[int]] = None,
                         min_area: int = 1) -> List[Blob]:
    f = arr(frame)
    wanted = None if colors is None else {int(c) for c in colors}
    seen = np.zeros(f.shape, dtype=bool)
    out: List[Blob] = []
    rows, cols = f.shape[:2]
    for r in range(rows):
        for c in range(cols):
            if seen[r, c]:
                continue
            color = int(f[r, c])
            if wanted is not None and color not in wanted:
                seen[r, c] = True
                continue
            q = [(r, c)]
            seen[r, c] = True
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not seen[nx, ny] and int(f[nx, ny]) == color:
                        seen[nx, ny] = True
                        q.append((nx, ny))
            if len(pts) >= min_area:
                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                out.append(Blob(color, (min(rs), min(cs), max(rs), max(cs)),
                                len(pts), (sum(rs) / len(pts), sum(cs) / len(pts))))
    return sorted(out, key=lambda b: (b.color, b.bbox))


def block_signatures(frame, cell: int = 4) -> Dict[Tuple[int, int], Tuple[int, ...]]:
    """Partition a frame into fixed cells and return each cell's color signature."""
    f = arr(frame)
    out = {}
    for r in range(0, f.shape[0], cell):
        for c in range(0, f.shape[1], cell):
            out[(r // cell, c // cell)] = tuple(int(v) for v in sorted(np.unique(f[r:r+cell, c:c+cell])))
    return out


def object_candidates(frame, cell: int = 4, min_area: int = 4) -> List[dict]:
    """A compact, game-agnostic object list from color components and cell signatures."""
    f = arr(frame)
    blobs = connected_components(f, min_area=min_area)
    sigs = block_signatures(f, cell)
    objects = []
    for b in blobs:
        r0, c0, r1, c1 = b.bbox
        objects.append({
            "color": b.color,
            "bbox": b.bbox,
            "top_left": b.top_left,
            "size": b.size,
            "area": b.area,
            "centroid": b.centroid,
            "cell": (r0 // cell, c0 // cell),
            "cell_sig": sigs.get((r0 // cell, c0 // cell)),
        })
    return objects


def frame_delta(before, after) -> dict:
    a, b = arr(before), arr(after)
    ys, xs = np.where(a != b)
    if len(ys) == 0:
        return {"count": 0, "bbox": None, "samples": []}
    samples = [(int(y), int(x), int(a[y, x]), int(b[y, x])) for y, x in zip(ys[:80], xs[:80])]
    return {
        "count": int(len(ys)),
        "bbox": (int(ys.min()), int(xs.min()), int(ys.max()), int(xs.max())),
        "samples": samples,
    }


def action_deltas(env, actions: Sequence[int] = ACTIONS) -> Dict[int, dict]:
    base = arr(env.frame()).copy()
    out = {}
    for action in actions:
        clone = env.clone()
        clone.step(action)
        out[int(action)] = frame_delta(base, clone.frame())
    return out


def replay(env, actions: Sequence[int]):
    clone = env.clone()
    for action in actions:
        if clone.terminal():
            break
        clone.step(int(action))
    return clone


def path_result(env, actions: Sequence[int]) -> dict:
    clone = replay(env, actions)
    return {
        "levels_completed": int(clone.levels_completed),
        "terminal": bool(clone.terminal()),
        "path_len": len(actions),
        "colors": color_counts(clone.frame()),
        "objects": object_candidates(clone.frame()),
    }


def changed_signature(env, actions: Sequence[int], cell: int = 4):
    before = block_signatures(env.frame(), cell)
    clone = replay(env, actions)
    after = block_signatures(clone.frame(), cell)
    return {k: (before.get(k), after.get(k)) for k in sorted(set(before) | set(after))
            if before.get(k) != after.get(k)}


def bounded_bfs(env, goal_fn, actions: Sequence[int] = (UP, DOWN, LEFT, RIGHT, USE),
                key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Generic clone BFS over observational keys. Use small max_states first."""
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()
    start_key = key_fn(env)
    q = deque([(env.clone(), [])])
    seen = {start_key}
    while q and len(seen) <= max_states:
        node, path = q.popleft()
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth:
            continue
        for action in actions:
            child = node.clone()
            child.step(int(action))
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            q.append((child, path + [int(action)]))
    return None


def bounded_replay_bfs(env, goal_fn, action_fn,
                       key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Path-only BFS for games whose deep Arena clones become expensive.

    The queue retains compact action paths, not recursively deep-copied runtime
    states. Each node is reconstructed from one root clone. ``action_fn(node)``
    may return integer actions or coordinate tuples such as ``(6, x, y)``.
    """
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()

    def reconstruct(path):
        node = env.clone()
        for action in path:
            if isinstance(action, tuple):
                node.step(*action)
            else:
                node.step(int(action))
        return node

    start = reconstruct([])
    q = deque([[]])
    seen = {key_fn(start)}
    while q and len(seen) <= max_states:
        path = q.popleft()
        node = reconstruct(path)
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth or node.terminal():
            continue
        for action in action_fn(node):
            child_path = path + [action]
            child = reconstruct(child_path)
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            if goal_fn(child, child_path):
                return child_path
            q.append(child_path)
    return None


def level_goal(base_level: int):
    return lambda env, path: env.levels_completed > base_level

# Per-level players. Each play_level_K(env) ONLY composes legs from legs.py.
from legs import *  # noqa


def play_level_1(env):
    # Ascend the block tower, then step onto the prize revealed at its top.
    climb_to_prize(env)


def play_level_2(env):
    # Taller tower with fatal ceiling hazards, so the greedy ascent walks into
    # dead-end shafts: plan the climb by search instead, then commit it.
    plan_and_commit(env, climb_search)


def play_level_3(env):
    # Nearby hazards must be made safe before each timed crossing.
    plan_and_commit(env, local_hazard_climb_search)


def play_level_4(env):
    # Alternate gravity toggles with only context-safe support interactions.
    plan_and_commit(env, gravity_room_search)


def play_level_5(env):
    # The same gravity rooms span the full screen and require side support work.
    solve_gravity_rooms(env, max_states=550)


def play_level_6(env):
    # Supports staged in the opening room become the bridge to the final prize.
    cross_persistent_support_rooms(env)
import players

def solve(env):
    # dispatch to the per-level player for the current level, in a loop
    while not env.terminal():
        k = env.levels_completed + 1
        fn = getattr(players, f'play_level_{k}', None)
        if fn is None:
            return
        before = env.levels_completed
        fn(env)
        if env.levels_completed <= before:
            return  # no progress -> stop

"""Compact, fresh tests of level-7 support selection and moving objects."""

import json
import os
import sys

sys.path.insert(0, "/Users/sasha/gkm/arc/crack_lab")
import gkm_arena as arena
import gkm_legs as campaign

from legs import COL_ANCHORS, ROW_ANCHORS, _cell_shape, click_action
from probe_l7_raw_search import SEED


if campaign._workspace_taint_reason(os.getcwd()):
    raise SystemExit("tainted workspace")


PALETTE = {
    0: "v", 3: "#", 5: "D", 7: "T", 8: "g", 9: "A",
    10: ".", 11: "a", 12: "s", 14: "Y", 15: "h",
}


def cells(frame, color):
    return tuple(
        (i, j, _cell_shape(frame, i, j)[1])
        for i, y in enumerate(ROW_ANCHORS)
        for j, x in enumerate(COL_ANCHORS)
        if int(frame[y][x]) == color
    )


def lattice(frame):
    return "/".join(
        "".join(PALETTE.get(int(frame[y][x]), "?") for x in COL_ANCHORS)
        for y in ROW_ANCHORS
    )


def crop(frame, i, j, color):
    r0, c0 = 6 * i, 13 + 6 * j
    return "/".join(
        "".join("x" if int(frame[r][c]) == color else "." for c in range(c0, c0 + 6))
        for r in range(r0, r0 + 6)
    )


def state(node):
    if node.terminal():
        return ("dead",)
    frame = node.frame()
    return (
        "alive",
        cells(frame, 9),
        cells(frame, 12),
        cells(frame, 0),
        cells(frame, 7),
        lattice(frame),
    )


def replay(root, actions):
    node = root.clone()
    for action in actions:
        node.step(*action)
        if node.terminal():
            break
    return node


def probe(env):
    with open("checkpoint.json") as stream:
        for action in json.load(stream)["final_path"]:
            env.step(action)
    root = env.clone()
    frame = root.frame()
    print("ENTRY", state(root))
    for color in (9, 12, 15):
        for i, j, area in cells(frame, color):
            print("SHAPE", color, (i, j, area), crop(frame, i, j, color))

    supports = [(i, j) for i, j, _ in cells(frame, 12)]
    tests = [
        ("wait", [(7,)] * int(os.environ.get("WAIT_COUNT", "4"))),
        ("move_undo", [(4,), (7,), (7,)]),
        ("move_undo_branch", [(4,), (7,), (4,), (6, 9, 3), (4,)]),
        ("move2_undo", [(4,), (4,), (7,), (7,), (7,)]),
        ("one", [click_action(*supports[0]), (7,), (7,), (7,)]),
        (
            "support_undo_branch",
            [click_action(*supports[-1]), (7,), (4,), (6, 9, 3), (4,)],
        ),
        (
            "support_move_undo",
            [click_action(*supports[-1]), (4,), (7,), (7,), (7,)],
        ),
        (
            "two",
            [
                click_action(*supports[0]),
                click_action(*supports[-1]),
                (7,), (7,), (7,),
            ],
        ),
        ("flip", [(6, 3, 3)]),
        ("flip_move_undo", [(6, 3, 3), (4,), (7,), (7,), (7,)]),
        ("flip_wait", [(6, 3, 3), (7,), (7,), (7,)]),
    ]
    for name, actions in tests:
        node = root.clone()
        print("TEST", name, 0, state(node))
        for index, action in enumerate(actions, 1):
            node.step(*action)
            print("TEST", name, index, action, state(node))
            if node.terminal():
                break
        if not node.terminal():
            moved = cells(node.frame(), 0)
            for i, j, area in moved:
                print("DARK_SHAPE", name, (i, j, area), crop(node.frame(), i, j, 0))

    node = root.clone()
    held = []
    for index, action in enumerate(SEED, 1):
        before = node.frame()
        event = None
        if action[0] == 6:
            _, x, y = action
            if x <= 5:
                event = ("left", int(before[y][x]) if y < 63 else -1, y)
            else:
                i = min(range(10), key=lambda k: abs(ROW_ANCHORS[k] - y))
                j = min(range(8), key=lambda k: abs(COL_ANCHORS[k] - x))
                event = ("cell", i, j, *_cell_shape(before, i, j))
            held.append(event)
        elif action[0] == 7:
            event = held.pop() if held else None
        node.step(*action)
        if action[0] in (6, 7):
            print(
                "SEED_EVENT", index, action,
                "push" if action[0] == 6 else "pop", event,
                "held", len(held), "state", state(node)[:5],
            )
        if node.terminal():
            break


arena.run_program("bp35", probe)

"""Symbolic BFS for the reproduced hazard/support chamber."""

from collections import deque


BOARD = [
    "########",
    "########",
    "#####x#P",
    "#####x#.",
    "#####x..",
    "#####x..",
    "..P.Px#.",
    ".xx.Xx#.",
    ".x.X.x#.",
    ".x.P.P#.",
]

START = (6, 0, -1)  # row, column, gravity (-1 up, +1 down)
SUPPORTS = [
    (r, c)
    for r, row in enumerate(BOARD)
    for c, value in enumerate(row)
    if value in "xX"
]
INDEX = {cell: index for index, cell in enumerate(SUPPORTS)}
START_MASK = sum(
    1 << INDEX[(r, c)]
    for r, row in enumerate(BOARD)
    for c, value in enumerate(row)
    if value == "X"
)


def tile(r, c, mask):
    value = BOARD[r][c]
    if value in "xX":
        return "X" if mask & (1 << INDEX[(r, c)]) else "."
    return value


def settle(r, c, gravity, mask):
    while True:
        nr = r + gravity
        if nr < 0 or nr >= len(BOARD):
            return "exit", r, c, gravity
        value = tile(nr, c, mask)
        if value in "#X":
            return r, c, gravity, mask
        if value == "P":
            return None
        r = nr


def successors(state):
    r, c, gravity, mask = state
    for dc, name in ((-1, "L"), (1, "R")):
        nc = c + dc
        if not 0 <= nc < 8 or tile(r, nc, mask) in "#XP":
            continue
        child = settle(r, nc, gravity, mask)
        if child is not None:
            yield name, child
    child = settle(r, c, -gravity, mask)
    if child is not None:
        yield "G", child
    for cell, index in INDEX.items():
        if cell == (r, c):
            continue
        yield f"T{cell[0]}{cell[1]}", (r, c, gravity, mask ^ (1 << index))


def goal(state):
    r, c, _gravity, _mask = state
    return c == 5 and r <= 2


start = (*START, START_MASK)
queue = deque([(start, ())])
seen = {start}
positions = {start[:3]}
exits = []
while queue:
    state, path = queue.popleft()
    if goal(state):
        print({"steps": len(path), "state": state[:3], "path": path})
        break
    if len(path) >= 28:
        continue
    for action, child in successors(state):
        if child[0] == "exit":
            exits.append((child[3], child[2], path + (action,)))
            continue
        if child in seen:
            continue
        seen.add(child)
        positions.add(child[:3])
        queue.append((child, path + (action,)))
else:
    best_exits = {}
    for direction, column, path in exits:
        best_exits.setdefault((direction, column), path)
        if len(path) < len(best_exits[(direction, column)]):
            best_exits[(direction, column)] = path
    print(
        {
            "found": False,
            "seen": len(seen),
            "positions": sorted(positions),
            "exits": sorted(
                (direction, column, path)
                for (direction, column), path in best_exits.items()
            ),
        }
    )

"""Exhaust the single omitted action in the decoded 60-move witness."""

import json
import os
import sys

sys.path.insert(0, "/Users/sasha/gkm/arc/crack_lab")
import gkm_arena as arena
import gkm_legs as campaign

from legs import (
    _cell_shape,
    click_action,
)
from probe_level7_decoded_stage import decoded_route
from probe_level7_reward_recovery import avatar_cell, controls


if campaign._workspace_taint_reason(os.getcwd()):
    raise SystemExit("tainted workspace")


LEFT, RIGHT, UNDO = (3,), (4,), (7,)
NOOP = (6, 9, 3)
BASE = [*decoded_route(), LEFT, LEFT, LEFT, LEFT]


def visible_actions(frame):
    mode = os.environ.get("ACTION_MODE", "objects")
    actions = []
    if mode == "generic":
        actions.extend([LEFT, RIGHT, UNDO, NOOP, (6, 3, 3)])
    for i in range(10):
        for j in range(8):
            color, _area = _cell_shape(frame, i, j)
            if mode == "objects" and color in (8, 12, 14, 15):
                actions.append(click_action(i, j))
    return list(dict.fromkeys(actions))


def advance(node, actions):
    for action in actions:
        if node.terminal():
            break
        node.step(*action)
        if node.levels_completed > 6:
            break


def finish(node):
    if node.levels_completed > 6:
        return None
    if node.terminal():
        return None
    visible = controls(node.frame())
    if not visible:
        return None
    action = (6, 3, max(visible))
    node.step(*action)
    return action


def probe(env):
    with open("checkpoint.json") as stream:
        for action in json.load(stream)["final_path"]:
            env.step(action)

    root = env.clone()
    tracker = root.clone()
    shard = int(os.environ.get("SHARD", "0"))
    shards = int(os.environ.get("SHARDS", "1"))
    tested = 0
    outcomes = []

    for boundary in range(len(BASE) + 1):
        if tracker.terminal():
            break
        if boundary % shards != shard:
            if boundary < len(BASE):
                tracker.step(*BASE[boundary])
            continue
        actions = visible_actions(tracker.frame())
        for inserted in actions:
            tested += 1
            node = tracker.clone()
            advance(node, [inserted, *BASE[boundary:]])
            final = finish(node)
            route = [*BASE[:boundary], inserted, *BASE[boundary:]]
            if node.levels_completed > 6:
                if final is not None:
                    route.append(final)
                print(
                    "ONE_ACTION_WIN", boundary, inserted, len(route),
                    route, flush=True,
                )
                return
            if not node.terminal():
                outcomes.append(
                    (
                        len(controls(node.frame())),
                        avatar_cell(node.frame()),
                        boundary,
                        inserted,
                        final,
                    )
                )
            if tested % 100 == 0:
                print(
                    "ONE_ACTION_PROGRESS", shard, tested, boundary,
                    flush=True,
                )

        if boundary < len(BASE):
            tracker.step(*BASE[boundary])
            if tracker.terminal():
                break

    outcomes.sort(
        key=lambda item: (
            -item[0],
            item[1] is None,
            item[1] or (99, 99),
        )
    )
    print("ONE_ACTION_NONE", shard, tested, flush=True)
    for outcome in outcomes[:40]:
        print("ONE_ACTION_OPTION", outcome, flush=True)


if __name__ == "__main__":
    arena.run_program("bp35", probe)

"""Direct-clone BFS over level-7 gravity, movement, and nearby supports."""

from collections import deque
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, "/Users/sasha/gkm/arc/crack_lab")
import gkm_arena as arena

from legs import (
    COL_ANCHORS, ROW_ANCHORS, _cell_shape, click_action,
)
from perception import connected_components


LEFT = (3,)
RIGHT = (4,)
UP = (7, 0, 0)
OPENING = [
    RIGHT,
    RIGHT,
    RIGHT,
    (6, 39, 51),
    (6, 3, 3),
    RIGHT,
    (6, 3, 3),
    RIGHT,
]
INITIAL_STAGES = [
    (6, 27, 15),
    (6, 27, 27),
    (6, 39, 27),
    (6, 33, 9),
]


def avatar(frame):
    ys, xs = np.where(np.asarray(frame) == 9)
    if not len(xs):
        return None
    return int(round(float(xs.mean()))), int(round(float(ys.mean())))


def small_supports(frame):
    pixels = np.asarray(frame)
    out = []
    for y in range(1, 62):
        for x in range(1, 63):
            if (
                int(pixels[y, x]) == 12
                and all(
                    int(pixels[y + dy, x + dx]) == 12
                    for dy, dx in ((-1, -1), (-1, 1), (1, -1), (1, 1))
                )
                and all(
                    int(pixels[y + dy, x + dx]) != 12
                    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1))
                )
            ):
                out.append((x, y))
    return out


def choices(frame):
    position = avatar(frame)
    if position is None:
        return []
    ax, ay = position
    out = [LEFT, RIGHT, (7,)]
    controls = [
        blob
        for blob in connected_components(frame, colors=(8,), min_area=3)
        if blob.bbox[1] <= 5 and blob.bbox[0] < 63
    ]
    if controls:
        y, x = controls[0].centroid
        out.append((6, int(round(x)), int(round(y))))
    if os.environ.get("NO_SUPPORTS") == "1":
        return list(dict.fromkeys(out))
    if os.environ.get("LEAN_SUPPORTS") == "1":
        ai = min(range(10), key=lambda i: abs(ROW_ANCHORS[i] - ay))
        aj = min(range(8), key=lambda j: abs(COL_ANCHORS[j] - ax))
        for i in range(max(0, ai - 4), min(10, ai + 5)):
            for j in range(max(0, aj - 1), min(8, aj + 2)):
                if _cell_shape(frame, i, j)[0] in (12, 14):
                    out.append(click_action(i, j))
        return list(dict.fromkeys(out))
    for x, y in small_supports(frame):
        if abs(x - ax) <= 7 and abs(y - ay) <= 30:
            out.append((6, x, y))
    for blob in connected_components(frame, colors=(12,), min_area=6):
        y, x = blob.centroid
        x, y = int(round(x)), int(round(y))
        if abs(x - ax) <= 7 and abs(y - ay) <= 30:
            out.append((7, x, y))
    return list(dict.fromkeys(out))


def key(frame):
    return np.asarray(frame)[:63].tobytes()


def search(env):
    with open("checkpoint.json") as stream:
        prefix = json.load(stream)["final_path"]
    for action in prefix:
        env.step(action)
    base_level = int(env.levels_completed)
    stage_mask = int(os.environ.get("STAGE_MASK", "0"))
    for bit, action in enumerate(INITIAL_STAGES):
        if stage_mask & (1 << bit):
