        positions = [avatar_cell(node.frame())]
        for _ in range(5):
            node.step(*RIGHT)
            positions.append(avatar_cell(node.frame()))
            if node.levels_completed > base_level:
                print("TOP_PAIR_WIN", cells, route, "rights", flush=True)
