            if os.environ.get("SIGNED_ORIGIN") == "1":
                origin += signed_origin_delta(before, env.frame())
            else:
                origin = alignment(world, lattice(env.frame()), origin)
            merge(world, lattice(env.frame()), origin)
        observation["win"] = False
